import { Controller } from '@nestjs/common';

// 이 기능(FN-SFR-023-11)은 화면만 만든다.
// 원천세 신고서 API(생성·수정·확정·파일 생성)는 먼저 하는 작업이 만든다.
@Controller('api/v1')
export class FnSfr02311Controller {}

