import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Form, LookupSelect, Pairs, RefName, Select, TextInput, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

const REPORT_TYPES: [string, string][] = [
  ['WITHHOLDING_STATUS', '원천징수이행상황'],
  ['TUITION_REPAYMENT', '학자금상환'],
  ['LOCAL_INCOME_TAX', '지방소득세 특별징수'],
  ['RESIDENT_TAX_EMPLOYER', '주민세 종업원분'],
  ['PAYMENT_STATEMENT', '지급명세서'],
  ['SUBMISSION_SUMMARY', '제출집계표'],
];

const typeName = (v: unknown) => REPORT_TYPES.find(([k]) => k === v)?.[1] ?? String(v ?? '');

type Panel =
  | null
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'confirm'; row: Row }
  | { kind: 'file'; row: Row };

export default function FnSfr02311Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 신고서만 목록에 쌓는다.
  const [rows, setRows] = useState<Row[]>([]);
  const [panel, setPanel] = useState<Panel>(null);

  const patchRow = (id: unknown, patch: Row) => {
    setRows((old) => old.map((r) => (r.withholdingReportId === id ? { ...r, ...patch } : r)));
  };

  const pending = rows.filter((r) => r.status === '미확정').length;
  const confirmed = rows.filter((r) => r.status === '확정').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles items={[['생성한 신고서', rows.length], ['미확정', pending], ['확정', confirmed]]} />
      </section>
      <section className="box span-12">
        <h2>신고서 목록</h2>
        <Band total={rows.length}>
          <button type="button" onClick={() => setPanel({ kind: 'create' })}>집계 생성</button>
        </Band>
        <DataTable
          rows={rows}
          empty="이 화면에서 생성한 신고서가 없습니다."
          columns={[
            { key: 'withholdingReportId', label: '신고서 ID' },
            { key: 'paydayId', label: '급여 지급일', render: (r) => <RefName table="payday" role={role} value={r.paydayId} /> },
            { key: 'reportType', label: '신고 유형', render: (r) => typeName(r.reportType) },
            { key: 'reportDivision', label: '신고구분' },
            { key: 'attributionMonth', label: '귀속연월' },
            { key: 'status', label: '확정 여부', render: (r) => <Badge value={r.status} /> },
            { key: 'confirmedAt', label: '확정 일시', render: (r) => <DateText value={r.confirmedAt} time /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span>
                  {r.status === '미확정' && (
                    <button type="button" onClick={() => setPanel({ kind: 'edit', row: r })}>수정</button>
                  )}
                  {r.status === '미확정' && (
                    <button type="button" onClick={() => setPanel({ kind: 'confirm', row: r })}>확정</button>
                  )}
                  {r.status === '확정' && (
                    <button type="button" onClick={() => setPanel({ kind: 'file', row: r })}>전자신고 파일 생성</button>
                  )}
                </span>
              ),
            },
          ]}
        />
      </section>
      {panel?.kind === 'create' && (
        <CreatePanel
          role={role}
          onClose={() => setPanel(null)}
          onCreated={(row) => {
            setRows((old) => [row, ...old]);
            setPanel(null);
            notify('신고서를 생성했습니다.');
          }}
        />
      )}
      {panel?.kind === 'edit' && (
        <EditPanel
          role={role}
          row={panel.row}
          onClose={() => setPanel(null)}
          onSaved={(id, reportData) => {
            patchRow(id, { reportData });
            setPanel(null);
            notify('신고서를 수정했습니다.');
          }}
        />
      )}
      {panel?.kind === 'confirm' && (
        <ConfirmPanel
          role={role}
          row={panel.row}
          onClose={() => setPanel(null)}
          onConfirmed={(id, patch) => {
            patchRow(id, patch);
            setPanel(null);
            notify('신고서를 확정했습니다.');
          }}
        />
      )}
      {panel?.kind === 'file' && (
        <FilePanel
          role={role}
          row={panel.row}
          onClose={() => setPanel(null)}
          onDone={() => notify('전자신고 파일을 생성했습니다.')}
        />
      )}
    </div>
  );
}

function CreatePanel({ role, onClose, onCreated }: { role: string; onClose: () => void; onCreated: (row: Row) => void }) {
  const [paydayId, setPaydayId] = useState<number | string>('');
  const [attributionMonth, setAttributionMonth] = useState('');
  const [paymentMonth, setPaymentMonth] = useState('');
  const [reportDivision, setReportDivision] = useState('');
  const [reportType, setReportType] = useState('');
  const [reportData, setReportData] = useState('');

  const submit = async () => {
    if (paydayId === '' || !attributionMonth || !reportDivision || !reportType) {
      throw new Error('급여 지급일, 귀속연월, 신고구분, 신고 유형을 입력하세요.');
    }
    if (!/^\d{6}$/.test(attributionMonth) || (paymentMonth && !/^\d{6}$/.test(paymentMonth))) {
      throw new Error('귀속연월과 지급연월은 YYYYMM 형식으로 입력하세요.');
    }
    const body: Row = { paydayId, attributionMonth, reportDivision, reportType };
    if (paymentMonth) body.paymentMonth = paymentMonth;
    if (reportData) body.reportData = reportData;
    const res = await call<Row>('POST', '/withholding-reports', role, body);
    onCreated({
      withholdingReportId: res.withholdingReportId,
      status: res.status,
      reportData: res.reportData,
      paydayId,
      attributionMonth,
      paymentMonth,
      reportDivision,
      reportType,
    });
  };

  return (
    <Drawer title="신고서 집계 생성" onClose={onClose}>
      <Form onSubmit={submit} submit="생성">
        <Field label="급여 지급일" required>
          <LookupSelect table="payday" role={role} value={paydayId} onChange={setPaydayId} />
        </Field>
        <Field label="신고 유형" required>
          <Select value={reportType} onChange={setReportType} options={REPORT_TYPES} />
        </Field>
        <Field label="신고구분" required>
          <TextInput value={reportDivision} onChange={setReportDivision} />
        </Field>
        <Field label="귀속연월" required hint="YYYYMM">
          <TextInput value={attributionMonth} onChange={setAttributionMonth} />
        </Field>
        <Field label="지급연월" hint="YYYYMM">
          <TextInput value={paymentMonth} onChange={setPaymentMonth} />
        </Field>
        <Field label="신고 자료" wide>
          <TextInput value={reportData} onChange={setReportData} multiline />
        </Field>
      </Form>
    </Drawer>
  );
}

function EditPanel({ role, row, onClose, onSaved }: { role: string; row: Row; onClose: () => void; onSaved: (id: unknown, reportData: string) => void }) {
  const [reportData, setReportData] = useState(String(row.reportData ?? ''));

  const submit = async () => {
    if (!reportData) throw new Error('신고 자료를 입력하세요.');
    await call('PATCH', `/withholding-reports/${row.withholdingReportId}`, role, { reportData });
    onSaved(row.withholdingReportId, reportData);
  };

  return (
    <Drawer title="신고서 수정" onClose={onClose}>
      <Form onSubmit={submit} submit="저장">
        <Field label="신고 자료" required wide>
          <TextInput value={reportData} onChange={setReportData} multiline />
        </Field>
      </Form>
    </Drawer>
  );
}

function ConfirmPanel({ role, row, onClose, onConfirmed }: { role: string; row: Row; onClose: () => void; onConfirmed: (id: unknown, patch: Row) => void }) {
  const submit = async () => {
    const res = await call<Row>('POST', `/withholding-reports/${row.withholdingReportId}/confirm`, role, {});
    onConfirmed(row.withholdingReportId, { status: res.status, confirmedAt: res.confirmedAt });
  };

  return (
    <Drawer title="신고서 확정" onClose={onClose}>
      <Pairs
        items={[
          ['신고서 ID', String(row.withholdingReportId ?? '')],
          ['신고 유형', typeName(row.reportType)],
          ['귀속연월', String(row.attributionMonth ?? '')],
          ['신고 자료', String(row.reportData ?? '')],
        ]}
      />
      <Form onSubmit={submit} submit="확정" note="확정한 신고서는 정해진 절차 없이 수정할 수 없습니다." />
    </Drawer>
  );
}

function FilePanel({ role, row, onClose, onDone }: { role: string; row: Row; onClose: () => void; onDone: () => void }) {
  const [file, setFile] = useState<Row | null>(null);

  const submit = async () => {
    const res = await call<Row>('POST', `/withholding-reports/${row.withholdingReportId}/generate-file`, role, {});
    setFile(res);
    onDone();
  };

  return (
    <Drawer title="전자신고 파일 생성" onClose={onClose}>
      <Form onSubmit={submit} submit="파일 생성" note="생성한 파일을 내려받아 직접 제출합니다." />
      {file && (
        <div>
          <Pairs items={[['파일 이름', String(file.fileName ?? '')]]} />
          <Field label="파일 내용" wide>
            <TextInput value={file.fileContent} onChange={() => {}} multiline />
          </Field>
        </div>
      )}
    </Drawer>
  );
}
